import{_ as l,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2022-10-20","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-10-20","date":"2022-10-20T00:00:00.000Z","updated":"2022-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","数据恢复","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-10-20.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-10-20.md","lastUpdated":1780459816000}'),o={name:"posts/2022/Ceph_Performance_Meeting_2022-10-20.md"};function s(n,e,p,a,_,c){return t(),i("div",null,[...e[0]||(e[0]=[r("<p>本次Ceph性能会议主要讨论了以下议题：</p><ol><li><p><strong>Pull Request (PR) 讨论</strong>:</p><ul><li><strong>PR1</strong>: 来自Canonical的贡献者发现了一个与Unknown Cash相关的竞争条件，由Igor提交。这个修复看似简单，但可能存在潜在问题。</li><li><strong>PR2</strong>: Adam提交了关于改进Deferred决策的PR，讨论了可能的改进方向，包括完全移除Deferred路径的可能性。</li></ul></li><li><p><strong>性能问题</strong>:</p><ul><li>讨论了使用Secure Mode时客户端性能显著下降的问题，可能与SEO优化有关。</li></ul></li><li><p><strong>数据恢复</strong>:</p><ul><li>讨论了一个新的数据恢复方法，使用RocksDB快照进行数据恢复，但存在数据不一致的风险。</li></ul></li><li><p><strong>Deferred Writes优化</strong>:</p><ul><li>讨论了完全移除Deferred Writes的可能性，以及如何优化写入过程。</li></ul></li><li><p><strong>RocksDB的碎片化和Tombstones问题</strong>:</p><ul><li>讨论了RocksDB在处理大量删除操作时的性能问题，并提出了可能的解决方案。</li></ul></li></ol><p>会议决定：</p><ul><li>对PR1和PR2进行进一步的审查和测试。</li><li>详细分析Secure Mode的性能问题。</li><li>进一步讨论和测试数据恢复方法。</li><li>研究和实验Deferred Writes的优化方案。</li><li>开发和测试RocksDB的碎片化和Tombstones问题的解决方案。</li></ul><p>后续行动计划：</p><ul><li>对PR1和PR2进行代码审查和测试。</li><li>对Secure Mode的性能进行详细分析。</li><li>进一步讨论和测试数据恢复方法。</li><li>研究和实验Deferred Writes的优化方案。</li><li>开发和测试RocksDB的碎片化和Tombstones问题的解决方案。</li></ul>",6)])])}const g=l(o,[["render",s]]);export{u as __pageData,g as default};
